package com.fitfinance.service;
import com.fitfinance.dto.AuthDtos.*; import com.fitfinance.entity.User; import com.fitfinance.repository.UserRepository; import com.fitfinance.security.JwtService; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.UUID;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.findByEmail(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");User u=users.save(new User(r.name().trim(),email,encoder.encode(r.password())));return response(u);}
 public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);}
 public AuthResponse guest(){String email="guest@fitfinance.local";User guest=users.findByEmail(email).orElse(null);if(guest==null){try{guest=users.save(new User("Guest",email,encoder.encode(UUID.randomUUID().toString())));}catch(DataIntegrityViolationException concurrentCreation){guest=users.findByEmail(email).orElseThrow(()->concurrentCreation);}}return response(guest);}
 private AuthResponse response(User u){return new AuthResponse(jwt.create(u.getId()),u.getId(),u.getName(),u.getEmail());}}
